-- 1. Liqui Moly: Huile de boîte de vitesses à double embrayage 8100
DO $$
DECLARE prod_id text; BEGIN
  SELECT id INTO prod_id FROM public."Product"
  WHERE LOWER("nameFr") LIKE LOWER('%Huile de boîte de vitesses à double%')
     OR LOWER(slug) LIKE LOWER('%huile-de-boite-de-vitesses-a-d%')
  LIMIT 1;
  IF prod_id IS NOT NULL THEN
    INSERT INTO public."ProductVariant" (id, "productId", volume, price, "stockQty", "skuVariant")
    VALUES (gen_random_uuid()::text, prod_id, '1L', 60.0, 10, 'VAR-LIQU-HUILEDEB-1L')
    ON CONFLICT ("skuVariant") DO UPDATE SET price = 60.0, volume = '1L', "stockQty" = GREATEST("ProductVariant"."stockQty", 5);
    INSERT INTO public."ProductImage" (id, "productId", url, "isPrimary", "sortOrder")
    VALUES (gen_random_uuid()::text, prod_id, '/uploads/products/liqui-moly-huile-de-boite-de-vitesses-a-double-embrayage-810.jpg', true, 0)
    ON CONFLICT DO NOTHING;
  END IF;
END $$;

