  SELECT id INTO prod_id FROM public."Product"
  WHERE LOWER("nameFr") LIKE LOWER('%Top Tec 6100 0W-30%')
     OR LOWER(slug) LIKE LOWER('%top-tec-6100-0w-30%')
  LIMIT 1;
  IF prod_id IS NOT NULL THEN
    INSERT INTO public."ProductVariant" (id, "productId", volume, price, "stockQty", "skuVariant")
    VALUES (gen_random_uuid()::text, prod_id, '1L', 46.0, 10, 'VAR-LIQU-TOPTEC61-1L')
    ON CONFLICT ("skuVariant") DO UPDATE SET price = 46.0, volume = '1L', "stockQty" = GREATEST("ProductVariant"."stockQty", 5);
    INSERT INTO public."ProductVariant" (id, "productId", volume, price, "stockQty", "skuVariant")
    VALUES (gen_random_uuid()::text, prod_id, '5L', 174.0, 10, 'VAR-LIQU-TOPTEC61-5L')
    ON CONFLICT ("skuVariant") DO UPDATE SET price = 174.0, volume = '5L', "stockQty" = GREATEST("ProductVariant"."stockQty", 5);
